package de.fitnesscoach.agent;
import java.time.LocalDate;import java.util.*;import de.fitnesscoach.data.entity.*;import de.fitnesscoach.data.repository.FitnessCoachRepository;
final class AgentTestRepository implements FitnessCoachRepository{UserProfileEntity profile;GoalEntity goal;final List<TrainingAvailabilityEntity>availability=new ArrayList<>();final Map<LocalDate,DailyHealthEntity>health=new HashMap<>();final List<WorkoutEntity>workouts=new ArrayList<>();final List<PlannedWorkoutEntity>planned=new ArrayList<>();final Map<LocalDate,CheckInEntity>checkins=new HashMap<>();final Map<String,BaselineEntity>baselines=new HashMap<>();final Map<LocalDate,RecoveryEntity>recovery=new HashMap<>();final List<CoachMemoryEntity>memories=new ArrayList<>();final List<CoachDecisionEntity>decisions=new ArrayList<>();public UserProfileEntity getProfile(){return profile;}public void saveProfile(UserProfileEntity p){profile=p;}public List<TrainingAvailabilityEntity>getAvailability(){return availability;}public void saveAvailability(TrainingAvailabilityEntity a){availability.add(a);}public GoalEntity getActiveGoal(){return goal;}public long insertGoal(GoalEntity g){goal=g;return g.id;}public DailyHealthEntity getDailyHealth(LocalDate d){return health.get(d);}public void saveDailyHealth(DailyHealthEntity h){health.put(h.date,h);}public List<WorkoutEntity>getWorkouts(){return workouts;}public long insertWorkout(WorkoutEntity w){workouts.add(w);return w.id;}public void updateWorkout(WorkoutEntity w){}public List<PlannedWorkoutEntity>getPlannedWorkouts(LocalDate f,LocalDate t){List<PlannedWorkoutEntity>x=new ArrayList<>();for(PlannedWorkoutEntity p:planned)if(p.date!=null&&!p.date.isBefore(f)&&!p.date.isAfter(t))x.add(p);return x;}public PlannedWorkoutEntity getPlannedWorkout(long id){for(PlannedWorkoutEntity p:planned)if(p.id==id)return p;return null;}public long insertPlannedWorkout(PlannedWorkoutEntity w){planned.add(w);return w.id;}public void updatePlannedWorkout(PlannedWorkoutEntity w){}public CheckInEntity getCheckIn(LocalDate d){return checkins.get(d);}public void saveCheckIn(CheckInEntity c){checkins.put(c.date,c);}public BaselineEntity getBaseline(String m,int w){return baselines.get(m+":"+w);}public void saveBaseline(BaselineEntity b){baselines.put(b.metric+":"+b.windowDays,b);}public RecoveryEntity getRecovery(LocalDate d){return recovery.get(d);}public void saveRecovery(RecoveryEntity r){recovery.put(r.date,r);}public List<CoachMemoryEntity>getActiveMemories(){return memories;}public long insertMemory(CoachMemoryEntity m){memories.add(m);return m.id;}public List<CoachDecisionEntity>getDecisions(){return decisions;}public long insertDecision(CoachDecisionEntity d){decisions.add(d);return d.id;}}
